#!/usr/bin/env bash
#
# Removes runtime data generated by the server under data/.
#
# By default the whole data/ directory is deleted. The server recreates it on
# the next start and unpacks packaged templates again.
#
# Usage:
#   ./cleanup.sh                 # ask for confirmation, then remove data/
#   ./cleanup.sh --force         # remove data/ without asking
#   ./cleanup.sh --keep-content  # keep data/content/ and data/shared/
#
# data/content/ and data/shared/ are operator-owned (map metadata and uploaded
# archives), so use --keep-content when only the unpacked templates should go.

set -euo pipefail

ROOT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
DATA_DIR="$ROOT_DIR/data"

FORCE=0
KEEP_CONTENT=0

usage() {
    sed -n '2,15p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'
}

for arg in "$@"; do
    case "$arg" in
        -f|--force)        FORCE=1 ;;
        --keep-content)    KEEP_CONTENT=1 ;;
        -h|--help)         usage; exit 0 ;;
        *)
            echo "cleanup.sh: unknown option: $arg" >&2
            echo "Try '$0 --help' for more information." >&2
            exit 2
            ;;
    esac
done

# Safety guard: never operate on an unexpected path.
if [[ -z "$DATA_DIR" || "$DATA_DIR" == "/" || "$DATA_DIR" != "$ROOT_DIR/data" ]]; then
    echo "cleanup.sh: refusing to clean unexpected path: '${DATA_DIR}'" >&2
    exit 1
fi

if [[ ! -e "$DATA_DIR" ]]; then
    echo "Nothing to clean: $DATA_DIR does not exist."
    exit 0
fi

if [[ ! -d "$DATA_DIR" ]]; then
    echo "cleanup.sh: $DATA_DIR is not a directory" >&2
    exit 1
fi

if [[ "$KEEP_CONTENT" -eq 1 ]]; then
    echo "This will remove everything in $DATA_DIR except content/ and shared/."
else
    echo "This will remove the whole $DATA_DIR directory."
fi

if [[ "$FORCE" -eq 0 ]]; then
    if [[ ! -t 0 ]]; then
        echo "cleanup.sh: refusing to delete without confirmation; use --force" >&2
        exit 1
    fi
    read -r -p "Continue? [y/N] " answer
    case "$answer" in
        y|Y|yes|YES) ;;
        *) echo "Aborted."; exit 0 ;;
    esac
fi

if [[ "$KEEP_CONTENT" -eq 1 ]]; then
    find "$DATA_DIR" -mindepth 1 -maxdepth 1 \
        ! -name content ! -name shared \
        -exec rm -rf -- {} +
    echo "Cleaned $DATA_DIR (kept content/ and shared/)."
else
    rm -rf -- "$DATA_DIR"
    echo "Removed $DATA_DIR."
fi
